            if (wheight - top < domheight) {
                top = top - domheight - curcolordom.offsetHeight;
            } else {
                top = top;
            }
            if (top < 10) {
                top = 10;
            }
            this.dom.style.top = top + "px";
            this.dom.style.left = left + "px";
            this.pos = {
                left: left,
                top: top
            };
